import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import AdminSidebar from '../../components/AdminSidebar';
import toast from 'react-hot-toast';

const AdminPetsPage = () => {
  const { user, api } = useAuth();
  const navigate = useNavigate();
  const [pets, setPets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [editingPet, setEditingPet] = useState(null);
  const [formData, setFormData] = useState({
    name: '',
    type: 'Dog',
    sex: 'Male',
    age: 'Young',
    breed: '',
    status: 'Available',
    rescueStatus: 'Rescued',
    description: '',
    vaccinationHistory: '',
    medicalNotes: '',
    adoptionFee: 0,
    imageData: null
  });

  useEffect(() => {
    if (!user || user.role !== 'admin') {
      navigate('/admin/login');
      return;
    }
    fetchPets();
  }, [user, navigate]);

  const fetchPets = async () => {
    try {
      const response = await api.get('/pets');
      setPets(response.data);
    } catch (error) {
      console.error('Error fetching pets:', error);
      toast.error('Failed to load pets');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const petData = {
      name: formData.name,
      type: formData.type,
      sex: formData.sex,
      age: formData.age,
      breed: formData.breed,
      status: formData.status,
      rescueStatus: formData.rescueStatus,
      description: formData.description,
      vaccinationHistory: formData.vaccinationHistory,
      medicalNotes: formData.medicalNotes,
      adoptionFee: Number(formData.adoptionFee) || 0,
      imageData: formData.imageData
    };

    try {
      if (editingPet) {
        await api.put(`/pets/${editingPet._id}`, petData);
        toast.success('Pet updated successfully!');
      } else {
        await api.post('/pets', petData);
        toast.success('Pet added successfully!');
      }
      fetchPets();
      setShowModal(false);
      setEditingPet(null);
      setFormData({
        name: '',
        type: 'Dog',
        sex: 'Male',
        age: 'Young',
        breed: '',
        status: 'Available',
        rescueStatus: 'Rescued',
        description: '',
        vaccinationHistory: '',
        medicalNotes: '',
        adoptionFee: 0,
        imageData: null
      });
    } catch (error) {
      console.error('Error saving pet:', error);
      toast.error(error.response?.data?.message || 'Failed to save pet');
    }
  };

  const handleDelete = async (petId) => {
    if (window.confirm('Are you sure you want to delete this pet?')) {
      try {
        await api.delete(`/pets/${petId}`);
        toast.success('Pet deleted successfully!');
        fetchPets();
      } catch (error) {
        toast.error('Failed to delete pet');
      }
    }
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData({ ...formData, imageData: reader.result });
      };
      reader.readAsDataURL(file);
    }
  };

  const filteredPets = pets.filter(pet => {
    if (searchTerm && !pet.name.toLowerCase().includes(searchTerm.toLowerCase())) {
      return false;
    }
    return true;
  });

  if (loading) {
    return (
      <div style={{ display: 'flex' }}>
        <AdminSidebar />
        <div style={{ flex: 1, padding: '2rem' }}>Loading...</div>
      </div>
    );
  }

  return (
    <div style={{ display: 'flex' }}>
      <AdminSidebar />
      <main style={{ flex: 1, padding: '2rem', background: '#FFFBF7' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '2rem' }}>
          <h1 style={{ fontSize: '2rem', color: '#936E5C' }}>MANAGE PETS</h1>
          <button onClick={() => setShowModal(true)} style={{
            background: '#FFC2AE',
            border: 'none',
            padding: '12px 24px',
            borderRadius: '60px',
            fontWeight: 'bold',
            cursor: 'pointer'
          }}>
            + Add New Pet
          </button>
        </div>

        <div style={{ marginBottom: '2rem' }}>
          <input
            type="text"
            placeholder="Search by name..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            style={{
              width: '300px',
              padding: '12px 20px',
              borderRadius: '60px',
              border: '1px solid #FFDDD0',
              background: 'white'
            }}
          />
        </div>

        <div style={{ background: 'white', borderRadius: '32px', overflow: 'hidden', border: '1px solid #FFE2D4' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ background: '#FFF7F0' }}>
                <th style={{ padding: '1rem', textAlign: 'left' }}>Name</th>
                <th style={{ padding: '1rem', textAlign: 'left' }}>Type</th>
                <th style={{ padding: '1rem', textAlign: 'left' }}>Status</th>
                <th style={{ padding: '1rem', textAlign: 'left' }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredPets.map(pet => (
                <tr key={pet._id} style={{ borderBottom: '1px solid #FFE2D4' }}>
                  <td style={{ padding: '1rem' }}><strong>{pet.name}</strong></td>
                  <td style={{ padding: '1rem' }}>{pet.type}</td>
                  <td style={{ padding: '1rem' }}>
                    <span style={{
                      padding: '0.2rem 0.8rem',
                      borderRadius: '60px',
                      background: pet.status === 'Available' ? '#E0F2E9' : '#FFE5D9',
                      color: pet.status === 'Available' ? '#4B7B6E' : '#C27D62'
                    }}>
                      {pet.status}
                    </span>
                  </td>
                  <td style={{ padding: '1rem' }}>
                    <button onClick={() => {
                      setEditingPet(pet);
                      setFormData({
                        name: pet.name,
                        type: pet.type,
                        sex: pet.sex,
                        age: pet.age,
                        breed: pet.breed || '',
                        status: pet.status,
                        rescueStatus: pet.rescueStatus,
                        description: pet.description,
                        vaccinationHistory: pet.vaccinationHistory || '',
                        medicalNotes: pet.medicalNotes || '',
                        adoptionFee: pet.adoptionFee || 0,
                        imageData: pet.imageData || null
                      });
                      setShowModal(true);
                    }} style={{ marginRight: '10px', background: '#FEF0EA', border: 'none', padding: '6px 12px', borderRadius: '60px', cursor: 'pointer' }}>
                      Edit
                    </button>
                    <button onClick={() => handleDelete(pet._id)} style={{ background: '#FEF0EA', border: 'none', padding: '6px 12px', borderRadius: '60px', cursor: 'pointer', color: '#E57A5C' }}>
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Modal */}
        {showModal && (
          <div style={{
            position: 'fixed',
            top: 0,
            left: 0,
            width: '100%',
            height: '100%',
            background: 'rgba(0,0,0,0.4)',
            backdropFilter: 'blur(5px)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 1000
          }} onClick={() => setShowModal(false)}>
            <div style={{
              background: 'white',
              maxWidth: '600px',
              width: '90%',
              borderRadius: '48px',
              padding: '2rem',
              maxHeight: '85vh',
              overflowY: 'auto'
            }} onClick={(e) => e.stopPropagation()}>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '1.5rem' }}>
                <h2>{editingPet ? 'EDIT PET' : 'ADD NEW PET'}</h2>
                <button onClick={() => setShowModal(false)} style={{ background: 'none', border: 'none', fontSize: '1.5rem', cursor: 'pointer' }}>×</button>
              </div>
              <form onSubmit={handleSubmit}>
                <div style={{ marginBottom: '1rem' }}>
                  <label style={{ display: 'block', fontWeight: '600', marginBottom: '0.5rem' }}>Pet Name *</label>
                  <input type="text" value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} required style={{ width: '100%', padding: '10px', borderRadius: '24px', border: '1px solid #FFDDD0' }} />
                </div>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '1rem', marginBottom: '1rem' }}>
                  <div>
                    <label>Type</label>
                    <select value={formData.type} onChange={(e) => setFormData({ ...formData, type: e.target.value })} style={{ width: '100%', padding: '10px', borderRadius: '24px', border: '1px solid #FFDDD0' }}>
                      <option value="Dog">Dog</option>
                      <option value="Cat">Cat</option>
                    </select>
                  </div>
                  <div>
                    <label>Sex</label>
                    <select value={formData.sex} onChange={(e) => setFormData({ ...formData, sex: e.target.value })} style={{ width: '100%', padding: '10px', borderRadius: '24px', border: '1px solid #FFDDD0' }}>
                      <option value="Male">Male</option>
                      <option value="Female">Female</option>
                    </select>
                  </div>
                  <div>
                    <label>Age</label>
                    <select value={formData.age} onChange={(e) => setFormData({ ...formData, age: e.target.value })} style={{ width: '100%', padding: '10px', borderRadius: '24px', border: '1px solid #FFDDD0' }}>
                      <option value="Baby">Baby</option>
                      <option value="Young">Young</option>
                      <option value="Adult">Adult</option>
                      <option value="Senior">Senior</option>
                    </select>
                  </div>
                </div>
                <div style={{ marginBottom: '1rem' }}>
                  <label>Breed</label>
                  <input type="text" value={formData.breed} onChange={(e) => setFormData({ ...formData, breed: e.target.value })} style={{ width: '100%', padding: '10px', borderRadius: '24px', border: '1px solid #FFDDD0' }} />
                </div>
                <div style={{ marginBottom: '1rem' }}>
                  <label>Description</label>
                  <textarea rows="3" value={formData.description} onChange={(e) => setFormData({ ...formData, description: e.target.value })} style={{ width: '100%', padding: '10px', borderRadius: '24px', border: '1px solid #FFDDD0' }} />
                </div>
                <div style={{ marginBottom: '1rem' }}>
                  <label>Adoption Fee (PHP)</label>
                  <input type="number" value={formData.adoptionFee} onChange={(e) => setFormData({ ...formData, adoptionFee: parseInt(e.target.value) || 0 })} style={{ width: '100%', padding: '10px', borderRadius: '24px', border: '1px solid #FFDDD0' }} />
                </div>
                <div style={{ marginBottom: '1rem' }}>
                  <label>Upload Image</label>
                  <div style={{ background: '#FEF6F0', borderRadius: '60px', padding: '12px', border: '1px dashed #FFC1AE', cursor: 'pointer', textAlign: 'center' }} onClick={() => document.getElementById('petImage').click()}>
                    {formData.imageData ? 'Image selected' : 'Click to upload image'}
                  </div>
                  <input type="file" id="petImage" accept="image/*" onChange={handleImageChange} style={{ display: 'none' }} />
                </div>
                <button type="submit" style={{ background: '#FFC2AE', width: '100%', border: 'none', padding: '12px', borderRadius: '60px', fontWeight: 'bold', cursor: 'pointer' }}>
                  {editingPet ? 'Update Pet' : 'Save Pet'}
                </button>
              </form>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default AdminPetsPage;
